import gurobipy as gp
from gurobipy import GRB

env = gp.Env(empty=True)
env.setParam('LogFile', 'log.txt')
env.start()

model = gp.Model(env=env)

standard_stock = [150, 250, 300]
premium_stock = [30, 100, 70]
distance = [
    [0, 12, 18],
    [12, 0, 15],
    [18, 15, 0]
]

x = {}
y = {}

for i in range(3):
    for j in range(3):
        x[(i,j)] = model.addVar(name=f"x_{i}_{j}", lb=0)
        y[(i,j)] = model.addVar(name=f"y_{i}_{j}", lb=0)

obj = 0
for i in range(3):
    for j in range(3):
        obj += distance[i][j] * (x[(i,j)] + y[(i,j)])
model.setObjective(obj, GRB.MINIMIZE)

for j in range(3):
    expr = gp.LinExpr()
    for i in range(3):
        expr += x[(i,j)]
    model.addConstr(expr == 700/3, f"hub_std_{j}")
    expr = gp.LinExpr()
    for i in range(3):
        expr += y[(i,j)]
    model.addConstr(expr == 200/3, f"hub_prem_{j}")

for i in range(3):
    expr = gp.LinExpr()
    for j in range(3):
        expr += x[(i,j)]
    model.addConstr(expr <= standard_stock[i], f"dc_std_{i}")
    expr = gp.LinExpr()
    for j in range(3):
        expr += y[(i,j)]
