customer_distances = []
for i in range(len(customers)):
    row = []
    for j in range(len(customers)):
        row.append(distance(customers[i][:2], customers[j][:2]))
    customer_distances.append(row)

# Create model
model = gp.Model(env=env)

# Decision variables
# x[i][j]: 1 if customer j is assigned to truck i
x = {}
for i in range(5):  # up to 5 trucks
    x[i] = {}
    for j in range(len(customers)):
        x[i][j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

